select policyname, cmd, roles, qual, with_check from pg_policies where schemaname = 'storage' and tablename = 'objects' and (qual ilike '%avatars%' or with_check ilike '%avatars%' or qual ilike '%song-covers%' or with_check ilike '%song-covers%') order by qual, cmd, policyname;
do $$ declare adm text; lid text; org uuid := '00000000-0000-0000-0000-000000000001'::uuid; r text := ''; n int; begin
select m.email into adm from public.organization_members om join public.members m on m.id = om.person_id where om.role in ('owner', 'admin') and om.organization_id = org and m.email is not null limit 1;
select m.email into lid from public.team_members tm join public.members m on m.id = tm.member_id where tm.is_leader and tm.organization_id = org and m.email is not null and not exists (select 1 from public.organization_members om where om.person_id = tm.member_id and om.role in ('owner', 'admin')) limit 1;
if adm is null or lid is null then raise exception 'Falta un administrador o un líder que no sea administrador para probar'; end if;
begin insert into storage.objects (bucket_id, name) values ('avatars', 'prueba-053c-existente.png'), ('song-covers', 'prueba-053c-existente.png'); exception when others then r := r || 'ERROR INESPERADO en la preparación (' || sqlstate || ', ' || sqlerrm || '); '; end;
set local role anon;
begin insert into storage.objects (bucket_id, name) values ('avatars', 'prueba-053c-anon.png'); r := r || 'FALLO: anon subió a avatars; '; exception when insufficient_privilege then r := r || 'OK: anon no sube a avatars; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin update storage.objects set name = name where bucket_id = 'avatars'; get diagnostics n = row_count; r := r || case when n = 0 then 'OK: anon no reemplaza en avatars; ' else 'FALLO: anon reemplazó en avatars (' || n || ' filas); ' end; exception when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin insert into storage.objects (bucket_id, name) values ('song-covers', 'prueba-053c-anon.png'); r := r || 'FALLO: anon subió a song-covers; '; exception when insufficient_privilege then r := r || 'OK: anon no sube a song-covers; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin update storage.objects set name = name where bucket_id = 'song-covers'; get diagnostics n = row_count; r := r || case when n = 0 then 'OK: anon no reemplaza en song-covers; ' else 'FALLO: anon reemplazó en song-covers (' || n || ' filas); ' end; exception when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin select count(*) into n from storage.objects where bucket_id in ('avatars', 'song-covers'); r := r || 'OK: anon sigue leyendo avatars y song-covers (las lecturas públicas no se tocan); '; exception when insufficient_privilege then r := r || 'FALLO: anon ya no lee avatars ni song-covers; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
reset role;
set local role authenticated; perform set_config('request.jwt.claims', json_build_object('email', adm, 'role', 'authenticated')::text, true);
begin insert into storage.objects (bucket_id, name) values ('song-covers', 'prueba-053c-admin.png'); r := r || 'OK: el administrador sube a song-covers; '; exception when insufficient_privilege then r := r || 'FALLO: el administrador no pudo subir a song-covers; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin update storage.objects set name = name where bucket_id = 'song-covers'; get diagnostics n = row_count; r := r || case when n >= 1 then 'OK: el administrador reemplaza en song-covers; ' else 'FALLO: el administrador no pudo reemplazar en song-covers (' || n || ' filas); ' end; exception when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin insert into storage.objects (bucket_id, name) values ('avatars', 'prueba-053c-admin.png'); r := r || 'FALLO: el administrador subió a avatars; '; exception when insufficient_privilege then r := r || 'OK: ni el administrador sube a avatars desde el navegador (lo hace el servidor); '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
reset role;
set local role authenticated; perform set_config('request.jwt.claims', json_build_object('email', lid, 'role', 'authenticated')::text, true);
begin insert into storage.objects (bucket_id, name) values ('song-covers', 'prueba-053c-lider.png'); r := r || 'FALLO: el líder subió a song-covers; '; exception when insufficient_privilege then r := r || 'OK: el líder no sube a song-covers; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin update storage.objects set name = name where bucket_id = 'song-covers' and name = 'prueba-053c-existente.png'; get diagnostics n = row_count; r := r || case when n = 0 then 'OK: el líder no reemplaza en song-covers; ' else 'FALLO: el líder reemplazó en song-covers (' || n || ' filas); ' end; exception when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
begin insert into storage.objects (bucket_id, name) values ('avatars', 'prueba-053c-lider.png'); r := r || 'FALLO: el líder subió a avatars; '; exception when insufficient_privilege then r := r || 'OK: el líder no sube a avatars; '; when others then r := r || 'ERROR INESPERADO (' || sqlstate || ', ' || sqlerrm || '); '; end;
reset role;
raise exception 'Resultado (se deshace todo): %', r; end $$;
